UPDATE public.association_info SET name_fr = 'Association Essaouira Darna', name_en = 'Essaouira Darna Association', tagline_fr = 'Prise en charge, hébergement et intégration des enfants en situation difficile dans la province d''Essaouira', tagline_en = 'Care, housing, and integration of children in difficult situations in the Essaouira province', description_fr = 'L''association Essaouira Darna a été fondée dans le but de fournir des soins complets, une éducation et un soutien psychosocial aux enfants orphelins, abandonnés ou vivant dans des conditions sociales difficiles dans la ville d''Essaouira et ses environs.', description_en = 'The Essaouira Darna Association was founded with the aim of providing comprehensive care, education, and psychosocial support to orphaned, abandoned children or those living in difficult social conditions in the city of Essaouira and its surroundings.', address_fr = 'Lotissement El Ghazoua, Essaouira, Maroc', address_en = 'El Ghazoua Subdivision, Essaouira, Morocco' WHERE id = 'd5983249-b21d-49e9-a5c3-d43d7e316848';

