-- Association Values
UPDATE public.association_values SET title_fr = 'Qualité des Services', title_en = 'Quality of Services', description_fr = 'Nos services sont gratuits pour garantir leur continuité et leur conformité à la loi 14/05', description_en = 'Our services are free to ensure their continuity and compliance with Law 14/05' WHERE id = '7269bc49-ba46-419c-8dc6-e263718d9a59';
UPDATE public.association_values SET title_fr = 'Partenariat', title_en = 'Partnership', description_fr = 'Nous sommes convaincus que le succès de toute action sociale repose sur la participation et la coopération entre les individus', description_en = 'We are convinced that the success of any social action relies on participation and cooperation between individuals' WHERE id = '76e41a06-d3e2-4054-951a-7322fc352401';
UPDATE public.association_values SET title_fr = 'Crédibilité', title_en = 'Credibility', description_fr = 'Dans toutes les initiatives qui nous aident à fournir l''assistance nécessaire aux enfants dans le besoin', description_en = 'In all initiatives that help us provide necessary assistance to children in need' WHERE id = 'bbd2e5f1-e37f-460c-ba29-537fa3dcbc56';
UPDATE public.association_values SET title_fr = 'Communication', title_en = 'Communication', description_fr = 'En communication constante avec nos partenaires', description_en = 'In constant communication with our partners' WHERE id = '35a1ed92-474c-416c-a47b-903d74009ba0';
UPDATE public.association_values SET title_fr = 'Solidarité', title_en = 'Solidarity', description_fr = 'Entre les bénéficiaires et le personnel de l''association', description_en = 'Between beneficiaries and association staff' WHERE id = 'f1e49b0c-5056-412f-a5f9-df94e9e8a25b';
UPDATE public.association_values SET title_fr = 'Transparence', title_en = 'Transparency', description_fr = 'Dans la gestion des affaires administratives et financières', description_en = 'In the management of administrative and financial affairs' WHERE id = '22043096-79b7-4a34-b11b-290213cae15a';
UPDATE public.association_values SET title_fr = 'Prise en Charge Globale', title_en = 'Comprehensive Care', description_fr = 'Fournir un abri, de la nourriture, des vêtements et des soins médicaux à chaque enfant résidant au foyer pour assurer sa croissance équilibrée et naturelle.', description_en = 'Providing shelter, food, clothing, and medical care to every child residing in the home to ensure their balanced and natural growth.' WHERE id = '3fac07dd-7f8d-4404-9fc0-56502e2e433b';
UPDATE public.association_values SET title_fr = 'Éducation et Orientation', title_en = 'Education and Guidance', description_fr = 'Suivre les enfants dans leur parcours éducatif, les guider et les qualifier pour entrer sur le marché du travail et devenir autonomes.', description_en = 'Following children in their educational paths, guiding them, and qualifying them to enter the job market and become self-reliant.' WHERE id = '356eb11d-6127-4526-a98e-add82b9a0edd';
UPDATE public.association_values SET title_fr = 'Transparence et Engagement', title_en = 'Transparency and Commitment', description_fr = 'Engagement envers les normes les plus élevées de gouvernance financière et de gestion administrative avec tous les partenaires, donateurs et institutions.', description_en = 'Commitment to the highest standards of financial governance and administrative management with all partners, donors, and institutions.' WHERE id = '0b23303d-9b0b-40a7-bdfb-a4b3d70c94b6';


-- About Content
UPDATE public.about_content SET title_fr = NULL, title_en = NULL, content_fr = 'L''association Essaouira Darna est une institution de protection sociale qui s''occupe des enfants abandonnés ou en situation difficile.', content_en = 'The Essaouira Darna Association is a social protection institution that cares for abandoned children or those in difficult situations.' WHERE id = 'ecdb2447-c66b-4b69-b5f9-1bceca21e202';
UPDATE public.about_content SET title_fr = NULL, title_en = NULL, content_fr = 'L''association a été fondée le 21 mars 2008 grâce à l''Initiative Nationale pour le Développement Humain lancée en 2005 à Essaouira.', content_en = 'The association was founded on March 21, 2008, thanks to the National Initiative for Human Development launched in 2005 in Essaouira.' WHERE id = '71c3ee57-5d2b-4cb2-a426-a6c77a97731f';
UPDATE public.about_content SET title_fr = NULL, title_en = NULL, content_fr = 'L''institution a été légalement autorisée en avril 2009, conformément à la décision n° 10/09 du Ministère de la Solidarité, de la Femme, de la Famille et du Développement Social, avec une capacité de 120 bénéficiaires.', content_en = 'The institution was legally authorized in April 2009, in accordance with Decision No. 10/09 of the Ministry of Solidarity, Women, Family and Social Development, with a capacity of 120 beneficiaries.' WHERE id = '552d72a4-df54-457f-a92b-3ebfd2040f43';
UPDATE public.about_content SET title_fr = NULL, title_en = NULL, content_fr = 'La gestion de l''institution est soumise à la loi n° 14-05 relative aux conditions d''ouverture et de gestion des établissements de protection sociale au Maroc.', content_en = 'The management of the institution is subject to Law No. 14-05 regarding the conditions for opening and managing social protection establishments in Morocco.' WHERE id = 'e7b57b74-9ee2-4808-b9ea-a526243626b5';
UPDATE public.about_content SET title_fr = 'Un avenir sans enfants en situation de rue', title_en = 'A future without street children', content_fr = 'À l''association Essaouira Darna, nous aspirons à ce que la province d''Essaouira soit totalement exempte du phénomène des enfants sans-abri ou en danger, et nous voulons garantir à chaque enfant de cette catégorie un abri digne et une chance égale pour une éducation de qualité et un développement sain.', content_en = 'At the Essaouira Darna Association, we aspire for the Essaouira province to be completely free of the phenomenon of homeless or at-risk children, and we want to guarantee every child in this category a dignified shelter and an equal chance for quality education and healthy development.' WHERE id = '24cd0445-70a4-4235-b994-921e95cb5492';
UPDATE public.about_content SET title_fr = 'Prise en charge, hébergement et intégration sociale', title_en = 'Care, housing, and social integration', content_fr = 'Notre mission est d''accueillir les enfants orphelins, abandonnés ou vivant dans une situation difficile, de leur fournir un abri sûr, une alimentation complète, des soins médicaux, une éducation et des activités récréatives, afin de préparer leur intégration effective dans leur environnement social et professionnel en tant que membres actifs et indépendants.', content_en = 'Our mission is to welcome orphaned, abandoned, or children living in difficult situations, to provide them with a safe shelter, comprehensive nutrition, medical care, education, and recreational activities, in order to prepare their effective integration into their social and professional environment as active and independent members.' WHERE id = 'b8033d4c-6aa1-4006-b0c8-df4c4037cd7a';

-- History Timeline
UPDATE public.history_timeline SET description_fr = 'En partenariat avec la préfecture d''Essaouira, le projet « Essaouira Darna » est né dans le cadre de l''INDH (Initiative Nationale pour le Développement Humain).', description_en = 'In partnership with the Essaouira prefecture, the ''Essaouira Darna'' project was born within the framework of the INDH (National Initiative for Human Development).' WHERE id = '09589337-3a40-4763-b199-2ba03376d4d1';
UPDATE public.history_timeline SET description_fr = 'L''association a officiellement ouvert ses portes et a commencé à accueillir des enfants abandonnés et ceux confrontés à des situations sociales difficiles, venant principalement d''autres associations comme l''Association Annajma et l''Association Nour Mogador.', description_en = 'The association officially opened its doors and began welcoming abandoned children and those facing difficult social situations, coming mainly from other associations such as the Annajma Association and the Nour Mogador Association.' WHERE id = '0d59a7c9-2e75-4930-a9a4-20e6a6da458c';
UPDATE public.history_timeline SET description_fr = 'L''institution a obtenu une autorisation légale conformément à la loi 14-05 et à la décision n° 10/09 du Ministère de la Solidarité, de la Femme et du Développement Social, avec une capacité de 60 bénéficiaires.', description_en = 'The institution obtained legal authorization in accordance with Law 14-05 and Decision No. 10/09 from the Ministry of Solidarity, Women, and Social Development, with a capacity of 60 beneficiaries.' WHERE id = '85100536-79af-4206-b4fb-d12989f6fc4d';
UPDATE public.history_timeline SET description_fr = 'L''institution a été autorisée, conformément à la loi 14-05, à augmenter sa capacité d''accueil à 120 bénéficiaires.', description_en = 'The institution was authorized, in accordance with Law 14-05, to increase its hosting capacity to 120 beneficiaries.' WHERE id = '6df6325b-841a-4f3d-8b9f-260b315c9e3a';
UPDATE public.history_timeline SET description_fr = 'L''institution est actuellement gérée par une association composée de sept membres, dont trois femmes.', description_en = 'The institution is currently managed by an association composed of seven members, including three women.' WHERE id = '2fa66d0e-d132-4b7f-a605-20096075c0f4';

-- Projects
UPDATE public.projects SET title_fr = 'Équipement et gestion de l''orphelinat Darna', title_en = 'Equipping and running the Darna orphanage', short_description_fr = 'Fournir un abri sûr et des soins complets aux enfants orphelins et en situation de rue à Essaouira.', short_description_en = 'Providing a safe shelter and comprehensive care for orphaned and street children in Essaouira.', long_description_fr = 'Ce projet continu vise à couvrir les coûts opérationnels du centre de soins à Essaouira (Darna), y compris l''alimentation, l''habillement, les soins médicaux et l''éducation pour les enfants résidents. Nous nous efforçons de fournir un environnement familial chaleureux qui soutient leur développement intégré et leur intégration dans la société.', long_description_en = 'This ongoing project aims to cover the operational costs of the care center in Essaouira (Darna), including nutrition, clothing, medical care, and education for the resident children. We strive to provide a warm family environment that supports their integrated development and integration into society.' WHERE id = 'da94ef41-4565-4fde-b6b6-de79bdabb8fc';
UPDATE public.projects SET title_fr = 'الرعاية الصحية والدعم الغذائي للأسر المعوزة', title_en = 'الرعاية الصحية والدعم الغذائي للأسر المعوزة', short_description_fr = 'تقديم المساعدات الغذائية الأساسية والرعاية الصحية الدورية للأسر الأكثر هشاشة.', short_description_en = 'تقديم المساعدات الغذائية الأساسية والرعاية الصحية الدورية للأسر الأكثر هشاشة.', long_description_fr = 'يركز هذا البرنامج على الفحوصات الطبية الدورية والتكفل بمصاريف الأدوية والعمليات الجراحية المستعجلة لفائدة الأطفال المستفيدين وأمهاتهم اللواتي يعشن في ظروف قاسية، إلى جانب توزيع قفف غذائية دورية.', long_description_en = 'يركز هذا البرنامج على الفحوصات الطبية الدورية والتكفل بمصاريف الأدوية والعمليات الجراحية المستعجلة لفائدة الأطفال المستفيدين وأمهاتهم اللواتي يعشن في ظروف قاسية، إلى جانب توزيع قفف غذائية دورية.' WHERE id = '879e3be8-cf5f-47c9-b1b3-011af93ebad1';
UPDATE public.projects SET title_fr = 'دعم التعليم الأولي والدمج المدرسي', title_en = 'دعم التعليم الأولي والدمج المدرسي', short_description_fr = 'تمويل الرسوم المدرسية واقتناء المحافظ والكتب المدرسية للأطفال المعوزين.', short_description_en = 'تمويل الرسوم المدرسية واقتناء المحافظ والكتب المدرسية للأطفال المعوزين.', long_description_fr = 'نسعى لضمان عدم انقطاع أي طفل عن الدراسة بسبب الصعوبات المادية. يشمل هذا المشروع شراء الكتب المدرسية، المحافظ، الدفاتر، والأدوات التعليمية، بالإضافة إلى توفير حصص الدعم والتقوية ودروس الدعم النفسي-التربوي للأطفال.', long_description_en = 'نسعى لضمان عدم انقطاع أي طفل عن الدراسة بسبب الصعوبات المادية. يشمل هذا المشروع شراء الكتب المدرسية، المحافظ، الدفاتر، والأدوات التعليمية، بالإضافة إلى توفير حصص الدعم والتقوية ودروس الدعم النفسي-التربوي للأطفال.' WHERE id = '9fb9674d-9684-4b74-b413-3e9a15e4d244';

